/**
 * useSceneVoiceovers — the kit video with each scene's voiceover spoken.
 *
 * Narration is generated by the studio's own path, unchanged:
 * `synthesizePendingNarration` (in-browser WebGPU TTS → WAV → the app's upload
 * endpoint), so every clip is a hosted URL the player, the post dock and the
 * export all play. Uploading needs a session; on a signed-out visit the
 * VoiceoverField starts the silent guest session, and generation waits for it.
 *
 * Generation runs ~800 ms after typing stops, one clip at a time, and is
 * cached by text — unchanged wording never regenerates, and a result whose
 * text has since changed is never laid down. A failure marks that scene
 * "error"; it never throws.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { VIDEO_SCENE_IDS, type VideoPlan, type VideoSceneId } from "@shared/video-plan";
import { makeAudioLayer, type CanvasState } from "@/lib/studio/editor-v2/canvas-state";
import { synthesizePendingNarration } from "@/lib/studio/page-narration";
import { useAuth } from "@/lib/auth";
import {
  recordedSceneAudio,
  sceneVoiceoverTexts,
  withSceneVoiceovers,
  withUploadedVoice,
  withVoiceMix,
  type SceneAudio,
} from "./scene-voiceover";

export type SceneVoiceoverStatus = "idle" | "generating" | "ready" | "error";
type StatusMap = Partial<Record<VideoSceneId, SceneVoiceoverStatus>>;
type AudioMap = Partial<Record<VideoSceneId, SceneAudio>>;

const DEBOUNCE_MS = 800;

/** Clips by text, shared across mounts (hosted URLs stay valid). */
const clipCache = new Map<string, Promise<SceneAudio>>();
/** One synthesis at a time — the engine is a single in-browser model. */
let queue: Promise<unknown> = Promise.resolve();

async function synthesize(base: CanvasState, text: string, voiceId: string | undefined): Promise<SceneAudio> {
  // One unanchored pending clip: the narration module voices + uploads it.
  const pending = makeAudioLayer({
    kind: "voiceover",
    source: { kind: "custom", url: "" },
    label: "Voiceover",
    durationSeconds: 0,
    text,
  });
  const result = await synthesizePendingNarration({ ...base, scenes: [], audioLayers: [pending] }, { voiceId });
  const clip = result.canvas.audioLayers[0];
  if (result.synthesised === 0 || clip?.source.kind !== "custom" || !clip.source.url) {
    throw new Error(result.skippedReason ?? "Narration could not be generated.");
  }
  return { text, url: clip.source.url, durationSeconds: clip.durationSeconds };
}

function clipFor(base: CanvasState, text: string, voiceId: string | undefined): Promise<SceneAudio> {
  // The same words in another voice are another clip.
  const key = `${voiceId ?? ""}\u0000${text}`;
  const cached = clipCache.get(key);
  if (cached) return cached;
  const next = queue.then(() => synthesize(base, text, voiceId));
  queue = next.catch(() => undefined);
  clipCache.set(key, next);
  // A failure is not cached: the next change of wording may try again.
  next.catch(() => clipCache.delete(key));
  return next;
}

export function useSceneVoiceovers(
  canvas: CanvasState | null,
  plan: VideoPlan,
): { canvas: CanvasState | null; status: StatusMap } {
  const { user } = useAuth();
  const texts = useMemo(() => sceneVoiceoverTexts(plan), [plan]);
  const voiceId = plan.voice?.source === "upload" ? undefined : plan.voice?.voiceId;
  const textsKey = JSON.stringify({ texts, voiceId });
  const [audio, setAudio] = useState<AudioMap>({});
  const [status, setStatus] = useState<StatusMap>({});
  // The wording each scene's "ready"/"error" status was settled for, so an
  // edit elsewhere doesn't reset (or re-announce) a scene that hasn't changed.
  const settled = useRef<Partial<Record<VideoSceneId, string>>>({});
  const hasCanvas = canvas !== null;

  useEffect(() => {
    const { texts: wanted, voiceId: voice } = JSON.parse(textsKey) as { texts: Partial<Record<VideoSceneId, string>>; voiceId?: string };
    const ids = VIDEO_SCENE_IDS.filter((id) => wanted[id]);
    setStatus((prev) => {
      const next: StatusMap = {};
      for (const id of ids) next[id] = settled.current[id] === wanted[id] ? prev[id] ?? "idle" : "idle";
      return next;
    });
    if (!user || !canvas || ids.length === 0) return;

    let stale = false;
    const base = canvas;
    const timer = window.setTimeout(() => {
      for (const id of ids) {
        const text = wanted[id] ?? "";
        // Cached clips resolve at once; only new wording shows "generating".
        if (settled.current[id] !== text) setStatus((prev) => ({ ...prev, [id]: "generating" }));
        const settle = (next: SceneVoiceoverStatus) => {
          settled.current = { ...settled.current, [id]: text };
          setStatus((prev) => ({ ...prev, [id]: next }));
        };
        clipFor(base, text, voice).then(
          (clip) => {
            if (stale) return;
            setAudio((prev) => ({ ...prev, [id]: clip }));
            settle("ready");
          },
          () => {
            if (!stale) settle("error");
          },
        );
      }
    }, DEBOUNCE_MS);
    return () => {
      stale = true;
      window.clearTimeout(timer);
    };
    // The canvas only seeds the synthesis call; its edits must not regenerate
    // (the effect reads it through the `hasCanvas` gate, not as a dependency).
  }, [textsKey, user, hasCanvas]);

  const voiced = useMemo(() => {
    if (!canvas) return null;
    // Only clips that still match the scene's current wording.
    // Recorded takes first; the AI voice fills the scenes without one.
    const current: AudioMap = { ...recordedSceneAudio(plan) };
    for (const id of VIDEO_SCENE_IDS) {
      const clip = audio[id];
      if (!current[id] && clip && clip.text === texts[id]) current[id] = clip;
    }
    return withVoiceMix(withUploadedVoice(withSceneVoiceovers(canvas, current), plan), plan);
  }, [canvas, audio, texts, plan]);

  return { canvas: voiced, status };
}
